/** Bizygomatic width in model units — landmark 234 to 454, the same pair
 *  geometry.js measures. Used to scale the mesh to a working canvas. */
const MODEL_BIZYGOMATIC = Math.abs(CANONICAL_XY[454][0] - CANONICAL_XY[234][0]);

/**
 * The canonical mesh as a 478-point landmark set in IMAGE pixels.
 *
 * Defaults reproduce the scale a real phone photo lands at after
 * `drawToCanvas`: a 768x1024 working canvas with a ~461px bizygomatic width,
 * which is what a measured run produced.
 *
 * Indices 468..477 are the iris points, absent from the canonical .obj. They
 * are filled with the eye centres so the set is the 478 points the pipeline
 * requires; no ROI reads them.
 */
export function canonicalFace({ bizygomatic = 461, cx = 384, cy = 512 } = {}) {
  const s = bizygomatic / MODEL_BIZYGOMATIC;
  const pts = CANONICAL_XY.map(([x, y]) => ({ x: cx + x * s, y: cy - y * s }));

  const centre = (ids) => {
    const sel = ids.map((i) => pts[i]);
    return {
      x: sel.reduce((a, p) => a + p.x, 0) / sel.length,
      y: sel.reduce((a, p) => a + p.y, 0) / sel.length,
    };
  };
  const rightEye = centre([33, 133, 159, 145]);
  const leftEye = centre([263, 362, 386, 374]);
  while (pts.length < 478) pts.push(pts.length < 473 ? { ...rightEye } : { ...leftEye });

  return pts;
}
